{"term":"G-spot","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"g_spot","is_novel_concept":false,"register":"clinical","crude":10,"technical":60,"recognition_pct_current":85,"recognition_pct_peak":88,"peak_year":null,"regional":null,"definition":"The Gräfenberg spot; a region on the anterior vaginal wall associated with heightened sensitivity and, in some accounts, female ejaculation.","english_term":"G-spot","english_translation_quality":"direct","notes":"Named after Ernst Gräfenberg; existence debated in sexology but widely accepted in popular culture; mainstreamed via sex-advice media in the 1980s–2000s."}
{"term":"A-spot","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"a_spot","is_novel_concept":false,"register":"clinical","crude":5,"technical":75,"recognition_pct_current":20,"recognition_pct_peak":22,"peak_year":null,"regional":null,"definition":"The anterior fornix erogenous zone; a sensitive region at the innermost anterior vaginal wall near the cervix, described as producing rapid lubrication when stimulated.","english_term":"A-spot","english_translation_quality":"direct","notes":"Also called AFE zone; first described by Malaysian sexologist Chua Chee Ann in 1993; significantly less culturally prominent than the G-spot."}
{"term":"cervix","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"cervix","concept":"cervix","is_novel_concept":false,"register":"clinical","crude":5,"technical":90,"recognition_pct_current":90,"recognition_pct_peak":90,"peak_year":null,"regional":null,"definition":"The lower, narrow end of the uterus that protrudes into the vaginal canal and can be contacted during deep penetration.","english_term":"cervix","english_translation_quality":"direct","notes":"From Latin 'neck of the uterus'; cervical stimulation is an erogenous response for some individuals; high cultural salience through cervical cancer screening discourse."}
{"term":"uterus","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"uterus","concept":"uterus","is_novel_concept":false,"register":"clinical","crude":3,"technical":95,"recognition_pct_current":95,"recognition_pct_peak":95,"peak_year":null,"regional":null,"definition":"The hollow muscular pelvic organ in which a fertilized ovum implants and a fetus develops; the womb.","english_term":"uterus","english_translation_quality":"direct","notes":"Uterine contractions occur during orgasm; politically charged in abortion discourse; lay synonym 'womb' carries a more emotional and literary register."}
{"term":"ovaries","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"ovary","concept":"ovaries","is_novel_concept":false,"register":"clinical","crude":3,"technical":90,"recognition_pct_current":95,"recognition_pct_peak":95,"peak_year":null,"regional":null,"definition":"The paired female gonads that produce ova and secrete estrogen and progesterone, governing sexual development and the reproductive cycle.","english_term":"ovaries","english_translation_quality":"direct","notes":"Sexual relevance is primarily endocrine rather than erogenous; widely known from secondary school biology; politically salient in reproductive rights contexts."}
{"term":"Bartholin's glands","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"bartholin_glands","is_novel_concept":false,"register":"clinical","crude":2,"technical":98,"recognition_pct_current":10,"recognition_pct_peak":10,"peak_year":null,"regional":null,"definition":"A pair of glands at the vaginal introitus that secrete mucus to lubricate the vaginal opening during sexual arousal.","english_term":"Bartholin's glands","english_translation_quality":"direct","notes":"Named after Caspar Bartholin the Younger; also called greater vestibular glands; Bartholin's cysts are the most common clinical presentation of this structure; extremely low lay recognition."}
{"term":"Skene's glands","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"skene_glands","is_novel_concept":false,"register":"clinical","crude":2,"technical":98,"recognition_pct_current":8,"recognition_pct_peak":8,"peak_year":null,"regional":null,"definition":"Small glands near the urethral opening in female anatomy, considered homologous to the male prostate and thought to be the source of female ejaculatory fluid.","english_term":"Skene's glands","english_translation_quality":"direct","notes":"Named after Alexander Skene; also called paraurethral or periurethral glands; directly implicated in squirting/female ejaculation research; near-zero lay recognition."}
{"term":"corpus cavernosum","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"erectile_tissue","concept":"corpus_cavernosum","is_novel_concept":false,"register":"classical_specialized","crude":2,"technical":99,"recognition_pct_current":20,"recognition_pct_peak":20,"peak_year":null,"regional":null,"definition":"Either of the paired columns of erectile tissue in the penis (and clitoris) that engorge with blood to produce erection.","english_term":"corpus cavernosum","english_translation_quality":"direct","notes":"From Latin 'cavernous body'; present in both penile and clitoral anatomy; plural corpora cavernosa; knowledge confined almost entirely to anatomy students and medical professionals."}
{"term":"corpus spongiosum","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"erectile_tissue","concept":"corpus_spongiosum","is_novel_concept":false,"register":"classical_specialized","crude":2,"technical":99,"recognition_pct_current":15,"recognition_pct_peak":15,"peak_year":null,"regional":null,"definition":"The single column of erectile tissue surrounding the male urethra that expands at its distal end to form the glans penis, keeping the urethra patent during erection.","english_term":"corpus spongiosum","english_translation_quality":"direct","notes":"From Latin 'spongy body'; no direct clitoral homologue; knowledge confined almost entirely to anatomy education and medical professionals."}
{"term":"glans clitoridis","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"clitoris","concept":"clitoral_glans","is_novel_concept":false,"register":"classical_specialized","crude":3,"technical":99,"recognition_pct_current":12,"recognition_pct_peak":12,"peak_year":null,"regional":null,"definition":"The exposed tip of the clitoris; the most densely innervated structure in the human body, homologous to the glans penis.","english_term":"clitoral glans","english_translation_quality":"direct","notes":"Full Latin anatomical designation; commonly referred to simply as 'the clitoris' in lay speech; the full clitoral body is largely internal; knowledge of this specific term is specialist-level."}
{"term":"clitoral hood","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"clitoris","concept":"clitoral_hood","is_novel_concept":false,"register":"clinical","crude":5,"technical":80,"recognition_pct_current":55,"recognition_pct_peak":55,"peak_year":null,"regional":null,"definition":"The fold of prepuce skin that covers and protects the glans clitoridis; homologous to the penile foreskin.","english_term":"clitoral hood","english_translation_quality":"direct","notes":"Also called preputium clitoridis; sensitivity varies by position and degree of retraction; subject of clitoral hood reduction (hoodectomy) in genital cosmetic surgery discourse."}
{"term":"hymen","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"hymen","is_novel_concept":false,"register":"clinical","crude":8,"technical":85,"recognition_pct_current":90,"recognition_pct_peak":90,"peak_year":null,"regional":null,"definition":"A thin mucous membrane partially occluding the vaginal opening; highly variable in form and presence; medically irrelevant as a virginity indicator.","english_term":"hymen","english_translation_quality":"direct","notes":"Named after the Greek god of marriage; one of the most culturally loaded anatomical terms — central to honor-killing, virginity testing, and female sexuality policing across many cultures; hymenoplasty is performed to 'restore' it."}
{"term":"introitus","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vagina","concept":"vaginal_opening","is_novel_concept":false,"register":"classical_specialized","crude":3,"technical":98,"recognition_pct_current":15,"recognition_pct_peak":15,"peak_year":null,"regional":null,"definition":"The entrance to the vaginal canal; the vaginal opening.","english_term":"vaginal opening","english_translation_quality":"direct","notes":"From Latin 'entrance'; used almost exclusively in obstetric and gynecological clinical writing; near-zero lay recognition."}
{"term":"vestibule","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"vulva","concept":"vulvar_vestibule","is_novel_concept":false,"register":"classical_specialized","crude":2,"technical":90,"recognition_pct_current":20,"recognition_pct_peak":20,"peak_year":null,"regional":null,"definition":"The space between the labia minora containing the urethral meatus, vaginal introitus, and the openings of Bartholin's and Skene's glands.","english_term":"vulvar vestibule","english_translation_quality":"direct","notes":"Borrowed from Latin vestibulum (entrance hall); strong polysemy with architectural meaning suppresses sexual associations; vestibulodynia is a common chronic pain condition affecting this region."}
{"term":"frenulum","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"genitalia","concept":"frenulum","is_novel_concept":false,"register":"clinical","crude":5,"technical":92,"recognition_pct_current":25,"recognition_pct_peak":25,"peak_year":null,"regional":null,"definition":"The sensitive band of connective tissue on the ventral surface of the glans penis (or clitoris) attaching to the prepuce; among the most densely innervated areas of the external genitalia.","english_term":"frenulum","english_translation_quality":"direct","notes":"From Latin 'little bridle'; polysemous with dental frenulum; frenulum tear ('banjo string injury') is a recognized penile injury; analogous structures exist at the clitoris and labia minora."}
{"term":"breast","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"breast","concept":"breast","is_novel_concept":false,"register":"clinical","crude":15,"technical":30,"recognition_pct_current":99,"recognition_pct_peak":99,"peak_year":null,"regional":null,"definition":"The mammary organ on the anterior chest wall; a secondary sex characteristic in females, functioning in lactation and widely regarded as an erogenous zone.","english_term":"breast","english_translation_quality":"direct","notes":"Register straddles clinical and everyday; sexual connotations are contextual; less crude than 'tit' or 'boob'; male breasts are clinically identical but culturally desexualized; subject of social media censorship asymmetry."}
{"term":"nipple","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"breast","concept":"nipple","is_novel_concept":false,"register":"clinical","crude":20,"technical":25,"recognition_pct_current":98,"recognition_pct_peak":98,"peak_year":null,"regional":null,"definition":"The erectile protrusion at the apex of the breast from which milk is expressed; an erogenous zone in all sexes.","english_term":"nipple","english_translation_quality":"direct","notes":"Male nipples are anatomically identical to female but socially desexualized; female nipples subject to disproportionate content moderation on social media platforms; crude score reflects mild contextual sexual charge rather than clinical usage."}
{"term":"areola","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"breast","concept":"areola","is_novel_concept":false,"register":"clinical","crude":5,"technical":85,"recognition_pct_current":70,"recognition_pct_peak":70,"peak_year":null,"regional":null,"definition":"The pigmented circular area of skin surrounding the nipple; contains Montgomery glands that lubricate the nipple during breastfeeding.","english_term":"areola","english_translation_quality":"direct","notes":"From Latin 'small open area'; recognition elevated by breastfeeding and body-positive discourse; size and pigmentation are highly variable; subject of cosmetic surgery interest (areola reduction)."}
{"term":"mammary gland","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"breast","concept":"breast","is_novel_concept":false,"register":"clinical","crude":3,"technical":95,"recognition_pct_current":75,"recognition_pct_peak":75,"peak_year":null,"regional":null,"definition":"The milk-secreting glandular tissue within the breast, comprising lobules and ducts that produce and channel milk to the nipple.","english_term":"mammary gland","english_translation_quality":"direct","notes":"From Latin 'mamma' (breast); used in biological and anatomical contexts rather than everyday clinical speech; shares concept slug with 'breast'; emphasis on function (lactation) over form."}
{"term":"pubic mound","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"mons_pubis","concept":"mons_pubis","is_novel_concept":false,"register":"clinical","crude":10,"technical":45,"recognition_pct_current":40,"recognition_pct_peak":40,"peak_year":null,"regional":null,"definition":"The rounded pad of fatty tissue over the pubic symphysis; the mons pubis described in lay English.","english_term":"pubic mound","english_translation_quality":"direct","notes":"English descriptive synonym for mons pubis; slightly more accessible to lay audiences; shares concept slug with mons pubis."}
{"term":"mons pubis","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"mons_pubis","concept":"mons_pubis","is_novel_concept":false,"register":"clinical","crude":3,"technical":90,"recognition_pct_current":35,"recognition_pct_peak":35,"peak_year":null,"regional":null,"definition":"The rounded eminence of fatty tissue overlying the pubic symphysis, covered by pubic hair post-puberty; the Latin anatomical term.","english_term":"pubic mound","english_translation_quality":"direct","notes":"Also called mons veneris (mound of Venus) in older texts; shares concept slug with 'pubic mound'; knowledge largely confined to those with anatomy education or gynecological discourse exposure."}
{"term":"pudendum","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"external_genitalia","concept":"genitalia","is_novel_concept":false,"register":"archaic","crude":10,"technical":70,"recognition_pct_current":10,"recognition_pct_peak":35,"peak_year":null,"regional":null,"definition":"The external genitalia, especially of females; an archaic clinical term derived from a Latin root meaning shame.","english_term":"external genitalia","english_translation_quality":"approximate","notes":"From Latin 'pudere' (to feel ashamed); the etymology literally encodes shame — 'the shameful parts'; plural pudenda; once standard in medical texts, now archaic; linguistically significant for honor-shame research because the shame is baked into the clinical term itself."}
{"term":"genitalia","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"external_genitalia","concept":"genitalia","is_novel_concept":false,"register":"clinical","crude":8,"technical":85,"recognition_pct_current":85,"recognition_pct_peak":85,"peak_year":null,"regional":null,"definition":"The reproductive organs, particularly the external genital structures; used collectively in medical, legal, and educational contexts.","english_term":"genitalia","english_translation_quality":"direct","notes":"Latin plural form; sometimes used as a false singular in informal English; preferred in formal clinical, legal, and policy writing over 'genitals'."}
{"term":"genitals","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"external_genitalia","concept":"genitalia","is_novel_concept":false,"register":"clinical","crude":10,"technical":70,"recognition_pct_current":90,"recognition_pct_peak":90,"peak_year":null,"regional":null,"definition":"The external reproductive organs; the common English plural of 'genital', used in everyday clinical and public health communication.","english_term":"genitals","english_translation_quality":"direct","notes":"More accessible and widely used than 'genitalia'; preferred in plain-language health communication and journalism; slightly higher crude score than 'genitalia' due to more colloquial feel."}
{"term":"gonads","lang":"en","script":"latin","romanization":null,"category":"organs","subcategory":"gonad","concept":"gonads","is_novel_concept":false,"register":"clinical","crude":5,"technical":80,"recognition_pct_current":75,"recognition_pct_peak":75,"peak_year":null,"regional":null,"definition":"The reproductive glands that produce gametes and sex hormones; the testes in males and ovaries in females.","english_term":"gonads","english_translation_quality":"direct","notes":"From Greek 'gone' (seed); covers both sexes, making it useful in gender-neutral clinical contexts; occasionally used humorously as an elevated euphemism for 'balls'; widely taught in secondary school biology."}
